mapper.select:
SELECT * FROM inventory_flow
WHERE product_id = #{productId} AND warehouse_id = #{warehouseId}
ORDER BY flow_time DESC

SELECT f.flow_time, p.sku_code, p.product_name, w.warehouse_name, CASE f.flow_type WHEN 'PURCHASE_IN' THEN '采购入库' WHEN 'SALE_OUT' THEN '销售出库' WHEN 'STOCK_CHECK' THEN '盘点调整' END as flow_type, f.quantity_change, f.quantity_after, f.related_order_no, u.real_name as operator_name, f.remark FROM inventory_flow f LEFT JOIN product p ON f.product_id = p.id LEFT JOIN warehouse w ON f.warehouse_id = w.id LEFT JOIN sys_user u ON f.operator_id = u.id WHERE 1=1
AND f.flow_time >= #{startTime}
AND f.flow_time <= #{endTime}
AND f.product_id = #{productId}
AND f.warehouse_id = #{warehouseId}
ORDER BY f.flow_time DESC
